// Linker option: /DELAYLOAD:External.dll

// Delayed function signature
extern void Delayed_API_Call();

// Custom error/notification hook setup
FARPROC WINAPI DelayLoadHook(unsigned dliNotify, PDelayLoadInfo pdli)
{
    // dliNotify: dliFailLoadLib, dliNotePreLoadLibrary, etc.
    if (dliNotify == dliFailLoadLib) {
        // Error handling during LoadLibrary() failure
        // Return replacement function address if possible
        return (FARPROC)NULL;
    }
    return (FARPROC)NULL;
}

// Global CRT pointer must be set for hook to activate
PfnDliHook __pfnDliFailureHook2 = DelayLoadHook;

void application_usage() {
    // DLL is loaded (and symbols bound) the first time this executes
    Delayed_API_Call();
}
